struct node {
    int data;
    node* left;
    node* right;
};

node* newNode(int data) {
    node* newNode = new node();
    newNode->data = data;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

node* solve(vector<int>& vec, int i) {
    if(i >= 7) {
        return NULL;
