    node* root = newNode(vec[i]);
    i = 2 * i;
    root->left = solve(vec, i + 1);
    root->right = solve(vec, i + 2);

    return root;
}

void create_tree(node*& root0, vector<int>& vec) {
    root0 = solve(vec, 0);
}

